use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct Message {
    pub role: String,
    pub content: serde_json::Value,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct CacheControl {
    #[serde(rename = "type")]
    pub cache_type: String,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct SystemBlock {
    #[serde(rename = "type")]
    pub block_type: String,
    pub text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cache_control: Option<CacheControl>,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct MessageRequest {
    pub model: String,
    pub max_tokens: u32,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub system: Vec<SystemBlock>,
    pub messages: Vec<Message>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub tools: Vec<Tool>,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct Tool {
    pub name: String,
    pub description: String,
    pub input_schema: serde_json::Value,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct TextContent {
    pub text: String,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct ToolUseContent {
    pub id: String,
    pub name: String,
    pub input: serde_json::Value,
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "type")]
pub enum ContentBlock {
    #[serde(rename = "text")]
    Text(TextContent),
    #[serde(rename = "tool_use")]
    ToolUse(ToolUseContent),
}

#[derive(Serialize, Deserialize, Debug)]
pub struct Usage {
    pub input_tokens: u32,
    pub output_tokens: u32,
    #[serde(default)]
    pub cache_creation_input_tokens: u32,
    #[serde(default)]
    pub cache_read_input_tokens: u32,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct MessageResponse {
    pub id: String,
    pub content: Vec<ContentBlock>,
    pub usage: Usage,
    pub stop_reason: String,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct BatchRequest {
    pub model: String,
    pub max_tokens: u32,
    pub messages: Vec<Message>,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct BatchResponse {
    pub id: String,
    pub processing_status: String,
    #[serde(default)]
    pub request_counts: BatchCounts,
}

#[derive(Serialize, Deserialize, Debug, Default)]
pub struct BatchCounts {
    pub processing: u32,
    pub succeeded: u32,
    pub errored: u32,
    pub expired: u32,
    pub cancelled: u32,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct BatchResult {
    pub result: BatchResultContent,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct BatchResultContent {
    pub message: MessageResponse,
}

// Pricing per model (as of Apr 2026)
pub struct ModelPricing {
    pub name: &'static str,
    pub input_per_1m: f64,
    pub output_per_1m: f64,
    pub cache_creation_per_1m: f64,
    pub cache_read_per_1m: f64,
}

impl ModelPricing {
    pub fn by_name(model: &str) -> Option<Self> {
        match model {
            "claude-haiku-4-5" => Some(ModelPricing {
                name: "Haiku 4.5",
                input_per_1m: 0.80,
                output_per_1m: 4.00,
                cache_creation_per_1m: 1.20,
                cache_read_per_1m: 0.08,
            }),
            "claude-sonnet-4-6" => Some(ModelPricing {
                name: "Sonnet 4.6",
                input_per_1m: 3.00,
                output_per_1m: 15.00,
                cache_creation_per_1m: 4.50,
                cache_read_per_1m: 0.30,
            }),
            "claude-opus-4-6" => Some(ModelPricing {
                name: "Opus 4.6",
                input_per_1m: 15.00,
                output_per_1m: 75.00,
                cache_creation_per_1m: 22.50,
                cache_read_per_1m: 1.50,
            }),
            _ => None,
        }
    }

    pub fn cost_for_message(&self, usage: &Usage) -> f64 {
        let input_cost = (usage.input_tokens as f64 / 1_000_000.0) * self.input_per_1m;
        let output_cost = (usage.output_tokens as f64 / 1_000_000.0) * self.output_per_1m;
        let cache_creation_cost = (usage.cache_creation_input_tokens as f64 / 1_000_000.0)
            * self.cache_creation_per_1m;
        let cache_read_cost =
            (usage.cache_read_input_tokens as f64 / 1_000_000.0) * self.cache_read_per_1m;

        input_cost + output_cost + cache_creation_cost + cache_read_cost
    }

    pub fn cache_savings(&self, usage: &Usage) -> f64 {
        let normal_cost =
            (usage.cache_read_input_tokens as f64 / 1_000_000.0) * self.input_per_1m;
        let cache_cost =
            (usage.cache_read_input_tokens as f64 / 1_000_000.0) * self.cache_read_per_1m;
        normal_cost - cache_cost
    }
}

