use anyhow::Result;
use clap::{Parser, Subcommand};
use tracing_subscriber::EnvFilter;

#[derive(Parser)]
#[command(name = "claude")]
#[command(version, about = "Universal Claude API client for prompt caching, vision, tool use, and benchmarking", long_about = None)]
struct Args {
    #[command(subcommand)]
    command: Commands,

    #[command(flatten)]
    verbose: clap_verbosity_flag::Verbosity<clap_verbosity_flag::InfoLevel>,
}

#[derive(Subcommand)]
enum Commands {
    /// Send message with optional prompt caching
    Message {
        /// User message
        #[arg(value_name = "TEXT")]
        prompt: String,

        /// System prompt
        #[arg(short, long, default_value = "You are a helpful assistant.")]
        system: String,

        /// Model to use
        #[arg(short, long, default_value = "claude-opus-4-6")]
        model: String,

        /// Enable prompt caching
        #[arg(short, long)]
        cache: bool,

        /// Output format (text, json, tokens)
        #[arg(short, long, default_value = "text")]
        format: String,
    },

    /// Analyze image with vision API
    Vision {
        /// Image URL
        #[arg(value_name = "URL")]
        url: String,

        /// Analysis prompt
        #[arg(short, long, default_value = "Analyze this image")]
        prompt: String,

        /// Model to use
        #[arg(short, long, default_value = "claude-opus-4-6")]
        model: String,
    },

    /// Benchmark multiple models
    Benchmark {
        /// Prompt to test
        #[arg(value_name = "TEXT")]
        prompt: String,

        /// Models to benchmark (comma-separated)
        #[arg(short, long, default_value = "claude-haiku-4-5,claude-sonnet-4-6,claude-opus-4-6")]
        models: String,

        /// Number of iterations
        #[arg(short, long, default_value = "1")]
        iterations: u32,

        /// Output format (table, csv, json)
        #[arg(short, long, default_value = "table")]
        format: String,
    },

    /// Submit batch job
    Batch {
        /// Input file (JSONL format)
        #[arg(value_name = "FILE")]
        input: String,

        /// Check batch status
        #[arg(short, long)]
        status: Option<String>,

        /// Retrieve batch results
        #[arg(short, long)]
        result: Option<String>,
    },

    /// Use tools (function calling)
    Tools {
        /// Tool call request (JSON)
        #[arg(value_name = "JSON")]
        request: String,

        /// Model to use
        #[arg(short, long, default_value = "claude-opus-4-6")]
        model: String,
    },

    /// Count tokens for prompt
    Tokens {
        /// Message to count
        #[arg(value_name = "TEXT")]
        message: String,

        /// System prompt
        #[arg(short, long)]
        system: Option<String>,

        /// Model to use
        #[arg(short, long, default_value = "claude-opus-4-6")]
        model: String,
    },

    /// Cost calculator
    Cost {
        /// Input tokens
        #[arg(short, long)]
        input: u32,

        /// Output tokens
        #[arg(short, long)]
        output: u32,

        /// Model (for pricing lookup)
        #[arg(short, long, default_value = "claude-opus-4-6")]
        model: String,

        /// Show cache savings
        #[arg(long)]
        cache: bool,
    },

    /// Show configuration
    Config {
        /// Show API key (masked by default)
        #[arg(long)]
        show_key: bool,
    },

    /// Start OpenAI-compatible HTTP server
    Serve {
        /// Port to listen on
        #[arg(short, long, default_value = "8000")]
        port: u16,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    // Setup logging
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| EnvFilter::new(args.verbose.log_level_filter().to_string())),
        )
        .with_writer(std::io::stderr)
        .init();

    // Load config
    dotenv::dotenv().ok();
    let config = config::Config::from_env()?;

    // Route command
    match args.command {
        Commands::Message {
            prompt,
            system,
            model,
            cache,
            format,
        } => {
            commands::message::run(&config, &prompt, &system, &model, cache, &format).await?
        }
        Commands::Vision { url, prompt, model } => {
            commands::vision::run(&config, &url, &prompt, &model).await?
        }
        Commands::Benchmark {
            prompt,
            models,
            iterations,
            format,
        } => commands::benchmark::run(&config, &prompt, &models, iterations, &format).await?,
        Commands::Batch {
            input,
            status,
            result,
        } => commands::batch::run(&config, &input, status, result).await?,
        Commands::Tools { request, model } => {
            commands::tools::run(&config, &request, &model).await?
        }
        Commands::Tokens {
            message,
            system,
            model,
        } => commands::tokens::run(&config, &message, system, &model).await?,
        Commands::Cost {
            input,
            output,
            model,
            cache,
        } => commands::cost::run(input, output, &model, cache)?,
        Commands::Config { show_key } => commands::config::run(&config, show_key)?,
        Commands::Serve { port } => {
            commands::serve::serve(
                config,
                commands::serve::ServeOptions { port },
            )
            .await?
        }
    }

    Ok(())
}

use crate::config::Config;
use crate::error::CliError;
use crate::models::*;
use reqwest::Client;
use std::time::Duration;
use tracing::debug;

pub struct ApiClient {
    client: Client,
    config: Config,
}

impl ApiClient {
    pub fn new(config: Config) -> Result<Self, CliError> {
        let client = Client::builder()
            .timeout(Duration::from_secs(config.timeout_secs))
            .build()?;

        Ok(ApiClient { client, config })
    }

    pub async fn send_message(&self, request: &MessageRequest) -> Result<MessageResponse, CliError> {
        let url = format!("{}/messages", self.config.base_url);
        debug!("Sending message to {}", url);

        let response = self
            .client
            .post(&url)
            .header("x-api-key", &self.config.api_key)
            .header("anthropic-version", &self.config.api_version)
            .json(request)
            .send()
            .await?;

        match response.status() {
            reqwest::StatusCode::OK => {
                let msg: MessageResponse = response.json().await?;
                Ok(msg)
            }
            reqwest::StatusCode::TOO_MANY_REQUESTS => {
                let retry_after = response
                    .headers()
                    .get("retry-after")
                    .and_then(|h| h.to_str().ok())
                    .and_then(|s| s.parse().ok())
                    .unwrap_or(60);
                Err(CliError::RateLimited(retry_after))
            }
            status => {
                let text = response.text().await.unwrap_or_default();
                Err(CliError::Api(format!(
                    "API error {}: {}",
                    status,
                    text
                )))
            }
        }
    }

    pub async fn count_tokens(&self, request: &MessageRequest) -> Result<u32, CliError> {
        let url = format!("{}/messages/count_tokens", self.config.base_url);
        debug!("Counting tokens");

        #[derive(serde::Deserialize)]
        struct TokenResponse {
            input_tokens: u32,
        }

        let response = self
            .client
            .post(&url)
            .header("x-api-key", &self.config.api_key)
            .header("anthropic-version", &self.config.api_version)
            .json(request)
            .send()
            .await?;

        match response.status() {
            reqwest::StatusCode::OK => {
                let token_resp: TokenResponse = response.json().await?;
                Ok(token_resp.input_tokens)
            }
            _ => {
                let text = response.text().await.unwrap_or_default();
                Err(CliError::Api(format!("Token count failed: {}", text)))
            }
        }
    }

    pub async fn submit_batch(&self, requests: Vec<BatchRequest>) -> Result<String, CliError> {
        let url = format!("{}/messages/batches", self.config.base_url);
        debug!("Submitting batch with {} requests", requests.len());

        #[derive(serde::Serialize)]
        struct BatchSubmission {
            requests: Vec<BatchRequestEnvelope>,
        }

        #[derive(serde::Serialize)]
        struct BatchRequestEnvelope {
            custom_id: String,
            params: BatchRequest,
        }

        let batch = BatchSubmission {
            requests: requests
                .into_iter()
                .enumerate()
                .map(|(i, params)| BatchRequestEnvelope {
                    custom_id: format!("req-{}", i),
                    params,
                })
                .collect(),
        };

        let response = self
            .client
            .post(&url)
            .header("x-api-key", &self.config.api_key)
            .header("anthropic-version", &self.config.api_version)
            .json(&batch)
            .send()
            .await?;

        match response.status() {
            reqwest::StatusCode::OK => {
                let batch_resp: BatchResponse = response.json().await?;
                Ok(batch_resp.id)
            }
            _ => {
                let text = response.text().await.unwrap_or_default();
                Err(CliError::Api(format!("Batch submission failed: {}", text)))
            }
        }
    }

    pub async fn check_batch_status(&self, batch_id: &str) -> Result<BatchResponse, CliError> {
        let url = format!("{}/messages/batches/{}", self.config.base_url, batch_id);
        debug!("Checking batch status: {}", batch_id);

        let response = self
            .client
            .get(&url)
            .header("x-api-key", &self.config.api_key)
            .header("anthropic-version", &self.config.api_version)
            .send()
            .await?;

        match response.status() {
            reqwest::StatusCode::OK => {
                let batch: BatchResponse = response.json().await?;
                Ok(batch)
            }
            _ => {
                let text = response.text().await.unwrap_or_default();
                Err(CliError::Api(format!("Batch status check failed: {}", text)))
            }
        }
    }
}

