use crate::error::CliError;
use std::env;

#[derive(Clone, Debug)]
pub struct Config {
    pub api_key: String,
    pub base_url: String,
    pub api_version: String,
    pub timeout_secs: u64,
    pub max_retries: u32,
}

impl Config {
    pub fn from_env() -> Result<Self, CliError> {
        let api_key = env::var("ANTHROPIC_API_KEY")
            .map_err(|_| CliError::Config("ANTHROPIC_API_KEY not set".to_string()))?;

        Ok(Config {
            api_key,
            base_url: env::var("ANTHROPIC_API_URL")
                .unwrap_or_else(|_| "https://api.anthropic.com/v1".to_string()),
            api_version: env::var("ANTHROPIC_API_VERSION")
                .unwrap_or_else(|_| "2023-06-01".to_string()),
            timeout_secs: env::var("ANTHROPIC_TIMEOUT")
                .ok()
                .and_then(|s| s.parse().ok())
                .unwrap_or(30),
            max_retries: env::var("ANTHROPIC_MAX_RETRIES")
                .ok()
                .and_then(|s| s.parse().ok())
                .unwrap_or(3),
        })
    }

    pub fn masked_key(&self) -> String {
        let len = self.api_key.len();
        if len <= 4 {
            "*".repeat(len)
        } else {
            format!("{}...{}", &self.api_key[..4], &self.api_key[len - 4..])
        }
    }
}

