pub async fn run(config: &Config, request: &str, model: &str) -> Result<()> {
    let client = super::create_client(config)?;

    // Parse tools from JSON request
    let request_json: serde_json::Value = serde_json::from_str(request)?;

    let tools: Vec<Tool> = request_json["tools"]
        .as_array()
        .map(|arr| {
            arr.iter()
                .filter_map(|t| serde_json::from_value(t.clone()).ok())
                .collect()
        })
        .unwrap_or_default();

    let message = Message {
        role: "user".to_string(),
        content: serde_json::json!(request_json["prompt"].as_str().unwrap_or("")),
    };

    let request = MessageRequest {
        model: model.to_string(),
        max_tokens: 4096,
        system: vec![],
        messages: vec![message],
        tools,
    };

    let response = client.send_message(&request).await?;

    println!("{}", serde_json::to_string_pretty(&response)?);

    eprintln!(
        "{}",
        format!(
            "✓ Tool call completed | Stop reason: {}",
            response.stop_reason.yellow()
        )
    );

    Ok(())
}

