use crate::config::Config;
use crate::models::*;
use anyhow::Result;
use colored::*;
use std::fs;
use tracing::info;

pub async fn run(
    config: &Config,
    input: &str,
    status: Option<String>,
    result: Option<String>,
) -> Result<()> {
    let client = super::create_client(config)?;

    if let Some(batch_id) = status {
        info!("Checking batch status: {}", batch_id);
        let batch = client.check_batch_status(&batch_id).await?;
        println!(
            "{}",
            serde_json::to_string_pretty(&batch).unwrap_or_default()
        );
        return Ok(());
    }

    if result.is_some() {
        // TODO: Implement result retrieval
        eprintln!("Result retrieval not yet implemented");
        return Ok(());
    }

    // Submit batch
    info!("Reading batch input from {}", input);
    let content = fs::read_to_string(input)?;

    let requests: Vec<BatchRequest> = content
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line)
                .map_err(|e| anyhow::anyhow!("Failed to parse JSON: {}", e))
        })
        .collect::<Result<Vec<_>>>()?;

    eprintln!("Submitting {} batch requests...", requests.len().to_string().cyan());
    let batch_id = client.submit_batch(requests).await?;

    println!("{}", batch_id.green().bold());
    eprintln!(
        "{}",
        format!(
            "✓ Batch submitted. Check status with: claude batch --status {}",
            batch_id
        )
        .green()
    );

    Ok(())
}

use crate::models::{
