/// Map OpenAI model names to Claude model names
pub fn map_openai_to_claude(model: &str) -> String {
    match model {
        "gpt-4o" => "claude-opus-4-6",
        "gpt-4o-mini" => "claude-haiku-4-5",
        "gpt-4-turbo" => "claude-sonnet-4-6",
        "gpt-4" => "claude-opus-4-6",
        "gpt-3.5-turbo" => "claude-haiku-4-5",
        // Passthrough Claude model names
        m if m.starts_with("claude-") => m,
        // Default fallback
        _ => "claude-opus-4-6",
    }
    .to_string()
}

/// Convert OpenAI ChatCompletionRequest to Claude MessageRequest
pub fn openai_to_claude(req: openai::ChatCompletionRequest) -> anthropic::MessageRequest {
    let model = map_openai_to_claude(&req.model);
    let max_tokens = req
        .max_completion_tokens
        .or(req.max_tokens)
        .unwrap_or(4096);

    // Convert messages
    let messages: Vec<anthropic::Message> = req
        .messages
        .iter()
        .map(|msg| anthropic::Message {
            role: msg.role.clone(),
            content: serde_json::Value::String(msg.content.clone().unwrap_or_default()),
        })
        .collect();

    anthropic::MessageRequest {
        model,
        max_tokens,
        system: vec![], // TODO: Extract system messages
        messages,
        tools: vec![],
    }
}

/// Convert Claude MessageResponse to OpenAI ChatCompletionResponse
pub fn claude_to_openai(
    resp: anthropic::MessageResponse,
    model: String,
) -> openai::ChatCompletionResponse {
    let content = resp
        .content
        .iter()
        .find_map(|c| match c {
            anthropic::ContentBlock::Text(t) => Some(t.text.clone()),
            _ => None,
        })
        .unwrap_or_default();

    openai::ChatCompletionResponse {
        id: resp.id,
        object: "chat.completion".to_string(),
        created: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs(),
        model,
        choices: vec![openai::ChatCompletionChoice {
            index: 0,
            message: openai::ChatCompletionMessage {
                role: "assistant".to_string(),
                content: Some(content),
            },
            finish_reason: resp.stop_reason.clone(),
            logprobs: None,
        }],
        usage: openai::ChatCompletionUsage {
            prompt_tokens: resp.usage.input_tokens,
            completion_tokens: resp.usage.output_tokens,
            total_tokens: resp.usage.input_tokens + resp.usage.output_tokens,
            prompt_tokens_details: None,
            completion_tokens_details: None,
        },
        system_fingerprint: None,
    }
}

