use crate::config::Config;
use crate::models::*;
use anyhow::Result;
use colored::*;
use serde_json::json;
use tracing::info;

pub async fn run(
    config: &Config,
    prompt: &str,
    system: &str,
    model: &str,
    cache: bool,
    format: &str,
) -> Result<()> {
    let client = super::create_client(config)?;

    info!("Sending message to {} (cache: {})", model, cache);

    let system_block = SystemBlock {
        block_type: "text".to_string(),
        text: system.to_string(),
        cache_control: if cache {
            Some(CacheControl {
                cache_type: "ephemeral".to_string(),
            })
        } else {
            None
        },
    };

    let message = Message {
        role: "user".to_string(),
        content: json!(prompt),
    };

    let request = MessageRequest {
        model: model.to_string(),
        max_tokens: 4096,
        system: vec![system_block],
        messages: vec![message],
        tools: vec![],
    };

    let response = client.send_message(&request).await?;

    match format {
        "text" => {
            if let Some(ContentBlock::Text(text)) = response.content.first() {
                println!("{}", text.text);
            }
        }
        "json" => {
            println!(
                "{}",
                serde_json::to_string_pretty(&response).unwrap_or_default()
            );
        }
        "tokens" => {
            println!("{}", json!({
                "input_tokens": response.usage.input_tokens,
                "output_tokens": response.usage.output_tokens,
                "cache_creation_input_tokens": response.usage.cache_creation_input_tokens,
                "cache_read_input_tokens": response.usage.cache_read_input_tokens,
                "total_tokens": response.usage.input_tokens + response.usage.output_tokens,
            }).to_string());
        }
        _ => eprintln!("Unknown format: {}", format),
    }

    // Print stats to stderr
    eprintln!(
        "{}",
        format!(
            "✓ {} | Input: {} | Output: {} | Cache write: {} | Cache read: {}",
            model.cyan(),
            response.usage.input_tokens.to_string().yellow(),
            response.usage.output_tokens.to_string().yellow(),
            response.usage.cache_creation_input_tokens.to_string().green(),
            response.usage.cache_read_input_tokens.to_string().blue(),
        )
    );

    if response.usage.cache_read_input_tokens > 0 {
        let pricing = ModelPricing::by_name(model).unwrap();
        let savings = pricing.cache_savings(&response.usage);
        eprintln!(
            "{}",
            format!("💰 Cache savings: ${:.4}", savings).green()
        );
    }

    Ok(())
}

