use crate::config::Config;
use crate::client::ApiClient;
use crate::models::openai;
use crate::server::transform;
use axum::{
    http::StatusCode,
    response::IntoResponse,
    routing::post,
    Json, Router,
};
use std::sync::Arc;
use tracing::{info, error};

#[derive(serde::Deserialize)]
pub struct ServeOptions {
    pub port: u16,
}

pub async fn serve(config: Config, opts: ServeOptions) -> anyhow::Result<()> {
    let config = Arc::new(config);
    let client = Arc::new(ApiClient::new((*config).clone())?);

    let app = Router::new()
        .route("/v1/messages", post(handle_messages))
        .with_state((config, client));

    let listener = tokio::net::TcpListener::bind(format!("127.0.0.1:{}", opts.port)).await?;
    info!("OpenAI-compatible server listening on http://127.0.0.1:{}", opts.port);
    info!("Proxying to Claude API");

    axum::serve(listener, app).await?;

    Ok(())
}

async fn handle_messages(
    state: axum::extract::State<(Arc<Config>, Arc<ApiClient>)>,
    Json(body): Json<openai::ChatCompletionRequest>,
) -> impl IntoResponse {
    let (_config, client) = state.0.clone();

    // Map OpenAI request to Claude format
    let claude_request = transform::openai_to_claude(body.clone());
    let model_used = claude_request.model.clone();

    // Send to Claude API
    match client.send_message(&claude_request).await {
        Ok(claude_response) => {
            // Convert Claude response back to OpenAI format
            let openai_response = transform::claude_to_openai(claude_response, model_used);
            (StatusCode::OK, Json(openai_response)).into_response()
        }
        Err(e) => {
            error!("Claude API error: {}", e);
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({
                    "error": {
                        "message": format!("Claude API error: {}", e),
                        "type": "api_error"
                    }
                })),
            )
                .into_response()
        }
    }
}

