use crate::config::Config;
use crate::models::*;
use anyhow::Result;
use colored::*;
use prettytable::{format, Table, cell, row};
use serde::Serialize;
use std::time::Instant;

pub async fn run(
    config: &Config,
    prompt: &str,
    models: &str,
    iterations: u32,
    format: &str,
) -> Result<()> {
    let client = super::create_client(config)?;
    let model_list: Vec<&str> = models.split(',').map(|s| s.trim()).collect();

    let mut results = vec![];

    for model in &model_list {
        for iter in 0..iterations {
            let message = Message {
                role: "user".to_string(),
                content: serde_json::json!(prompt),
            };

            let request = MessageRequest {
                model: model.to_string(),
                max_tokens: 1024,
                system: vec![],
                messages: vec![message],
                tools: vec![],
            };

            let start = Instant::now();
            match client.send_message(&request).await {
                Ok(response) => {
                    let elapsed = start.elapsed().as_millis();
                    let pricing = ModelPricing::by_name(model);
                    let cost = pricing.map(|p| p.cost_for_message(&response.usage));

                    results.push(BenchmarkResult {
                        model: model.to_string(),
                        iteration: iter + 1,
                        latency_ms: elapsed as u32,
                        input_tokens: response.usage.input_tokens,
                        output_tokens: response.usage.output_tokens,
                        cost: cost.unwrap_or(0.0),
                    });

                    eprintln!(
                        "✓ {} iter {} | {}ms | {} tokens",
                        model.cyan(),
                        iter + 1,
                        elapsed.to_string().yellow(),
                        (response.usage.input_tokens + response.usage.output_tokens)
                            .to_string()
                            .green()
                    );
                }
                Err(e) => {
                    eprintln!("✗ {} iter {} | Error: {}", model.red(), iter + 1, e);
                }
            }
        }
    }

    print_results(&results, format)?;
    Ok(())
}

#[derive(Serialize)]
struct BenchmarkResult {
    model: String,
    iteration: u32,
    latency_ms: u32,
    input_tokens: u32,
    output_tokens: u32,
    cost: f64,
}

fn print_results(results: &[BenchmarkResult], format: &str) -> Result<()> {
    match format {
        "table" => {
            let mut table = Table::new();
            table.set_format(*format::consts::FORMAT_BORDERS_ONLY);
            table.add_row(row![
                "Model",
                "Iteration",
                "Latency (ms)",
                "Input Tokens",
                "Output Tokens",
                "Cost ($)"
            ]);

            for result in results {
                table.add_row(row![
                    result.model,
                    result.iteration,
                    result.latency_ms,
                    result.input_tokens,
                    result.output_tokens,
                    format!("{:.6}", result.cost)
                ]);
            }

            table.printstd();
        }
        "csv" => {
            println!("model,iteration,latency_ms,input_tokens,output_tokens,cost");
            for result in results {
                println!(
                    "{},{},{},{},{},{}",
                    result.model,
                    result.iteration,
                    result.latency_ms,
                    result.input_tokens,
                    result.output_tokens,
                    result.cost
                );
            }
        }
        "json" => {
            println!("{}", serde_json::to_string_pretty(&serde_json::to_value(results)?)?);
        }
        _ => {}
    }

    Ok(())
}
